// ===============================================================================
// DAEMIND SRE - COMPILADOR DE ITENS CRÍTICOS E ALERTA EXECUTIVO
// ===============================================================================
const items = $input.all();

if (!items || items.length === 0 || !items[0].json?.item_nome) {
  return [{
    json: {
      has_critical_items: false,
      total_itens: 0,
      mensagem_alerta: ''
    }
  }];
}

let lines = [];
items.forEach((it, idx) => {
  const j = it.json;
  const icon = j.tipo_item === 'INSUMO_EMBALAGEM' ? '📦' : '🏷️';
  lines.push(`${idx + 1}. ${icon} *${j.item_nome}*\n   ↳ Saldo: *${j.saldo_atual}* (Mín: ${j.estoque_minimo}) | Fornecedor: ${j.fornecedor_nome || 'N/D'} (${j.fornecedor_contato || 'N/D'})`);
});

const msg = `⚠️ *DAEMIND SRE - ALERTA DE ESTOQUE CRÍTICO* ⚠️\n\nForam identificados *${items.length} itens* abaixo do ponto de reposição no *loja_db*:\n\n${lines.join('\n\n')}\n\n💡 *Ação Recomendada:* Efetuar pedido de compra junto aos fornecedores imediatamente.`;

return [{
  json: {
    has_critical_items: true,
    total_itens: items.length,
    itens_lista: items.map(i => i.json),
    mensagem_alerta: msg
  }
}];
